module.exports = async function(data) {
  const ready = data.build_payloads.ready;
  const failed = data.build_payloads.failed;
  const token = data.get_partner_token;
  const apiBase = data.prepare_matches.apiBaseUrl;
  const userId = data.prepare_matches.userId;
  const env = data.build_payloads.env;

  const partnerToken = token?.data?.result?.token || token?.result?.token || token?.accessToken || token?.access_token || token?.token;
  if (!partnerToken) {
    throw new Error('Failed to get partner access token');
  }

  const allResults = [];

  for (const f of failed) {
    allResults.push({ matchKey: f.matchKey, status: 'failed', error: f.error });
  }

  for (const match of ready) {
    try {
      const response = await fetch(apiBase + '/match/v1.0/saveMatch', {
        method: 'POST',
        headers: {
          'Authorization': 'Bearer ' + partnerToken,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(match.payload)
      });

      const result = await response.json();

      if (result.status === 'SUCCESS' && result.result) {
        allResults.push({
          matchKey: match.matchKey,
          status: 'submitted',
          duprMatchCode: result.result.matchCode,
          duprHashedMatchCode: result.result.hashedMatchCode
        });
      } else {
        allResults.push({
          matchKey: match.matchKey,
          status: 'failed',
          error: result.message || result.error || 'Unknown DUPR error'
        });
      }
    } catch (err) {
      allResults.push({
        matchKey: match.matchKey,
        status: 'unknown',
        error: err.message
      });
    }
  }

  return {
    results: allResults,
    resultsJson: JSON.stringify(allResults),
    userId,
    env,
    now: new Date().toISOString()
  };
}

