  if (!verified || verified.status !== 'SUCCESS' || !verified.results || !verified.results[0]) {
    throw new Error('DUPR identity verification failed');
  }

  const userInfo = verified.results[0];
  const now = new Date().toISOString();
  const accessExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();
  const refreshExpires = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();

  return {
    duprId: userInfo.duprId,
    userId: body.userId || data.$trigger.accountability?.user,
    accessToken: body.accessToken,
    refreshToken: body.refreshToken,
    singlesRating: null,
    doublesRating: null,
    environment: data.read_settings[0].environment || 'uat',
    now,
    accessExpires,
    refreshExpires
  };
}

