module.exports = async function(data) {
    const player = data.$trigger;
    const user = data.read_user;

    // 1. Validate player exists first
    if (!player || !player.userId) {
        throw new Error('Player must have a user account');
    }

    const totalMatches = (player.wins || 0) + (player.losses || 0);
    if (totalMatches === 0) {
        throw new Error('Player must have at least one recorded match');
    }

    // 2. Compare timestamps (use the LATEST of rating or stats)
    const playerRatingTs = Number(player.ratingUpdatedAt || 0);
    const playerStatsTs  = Number(player.statsUpdatedAt || 0);
    const playerLatestTs = Math.max(playerRatingTs, playerStatsTs);

    const userRatingTs = Number(user?.rating_updated_at || 0);
    const userStatsTs  = Number(user?.stats_updated_at || 0);
    const userLatestTs = Math.max(userRatingTs, userStatsTs);

    if (playerLatestTs <= userLatestTs) {
        throw new Error('Skip: data is not newer');
    }

    // 3. Derive day from statsUpdatedAt (fallback to today if missing)
    const statsDate = playerStatsTs 
        ? new Date(playerStatsTs).toISOString().split('T')[0]
        : new Date().toISOString().split('T')[0];

    return {
        player_day: `${player.userId}@${statsDate}`,
        player: player.userId,
        day: statsDate,
        wins: player.wins || 0,
        losses: player.losses || 0,
        rating: player.rating || 1500,
        stats_updated_at: playerStatsTs,
        rating_updated_at: playerRatingTs
    };
};

