const K_DOUBLES = 64;
const K_SINGLES = 36;
const MARGIN_WEIGHT = 0.15;
const PARTNER_GAP_FACTOR = 0.5;
const LOSS_UNDERDOG_BLEND = 1.0;
const RATING_FLOOR = 100;
const MAX_PARTNER_RATIO = 2.0;

const computeArithmeticMean = (team) => {
  if (!team || team.length === 0) return 1450;
  return team.reduce((sum, p) => sum + (Number(p.rating) || 1450), 0) / team.length;
};

const allocateInteger = (total, weights) => {
  const sum = weights.reduce((s, w) => s + w, 0);
  const norm = sum > 0
    ? weights.map((w) => w / sum)
    : weights.map(() => 1 / weights.length);
  const raw = norm.map((n) => n * total);
  const floors = raw.map((r) => Math.floor(r));
  const remainder = total - floors.reduce((s, f) => s + f, 0);
  const order = raw
    .map((r, i) => ({ i, frac: r - Math.floor(r) }))
    .sort((a, b) => b.frac - a.frac);
  const result = [...floors];
  for (let k = 0; k < remainder; k++) result[order[k % order.length].i] += 1;
  return result;
};

const capWeights = (weights, maxRatio) => {
  if (weights.length < 2) return weights;
  const max = Math.max(...weights);
  if (max <= 0) return weights;
  const minAllowed = max / maxRatio;
  return weights.map((w) => Math.max(w, minAllowed));
};

const calculateShift = (winners, losers, scoreW, scoreL) => {
  const ratingW = computeArithmeticMean(winners);
  const ratingL = computeArithmeticMean(losers);

  const margin = Math.abs(scoreW - scoreL);
  const multiplier = 1 + MARGIN_WEIGHT * Math.log(1 + margin);

  const K = winners.length === 1 ? K_SINGLES : K_DOUBLES;

  const expectedW = 1 / (1 + Math.pow(10, (ratingL - ratingW) / 400));
  const pool = Math.round(K * multiplier * (1 - expectedW));

  const winnerCredits = winners.map((p, i) => {
    const partner = winners[(i + 1) % winners.length];
    const gap = Math.abs(partner.rating - p.rating);
    const base = 1 - 1 / (1 + Math.pow(10, (ratingL - p.rating) / 400));
    const weaker = p.rating < partner.rating;
    const penalty = weaker
      ? Math.max(0.1, 1 - (PARTNER_GAP_FACTOR * gap) / 400)
      : 1;
    return base * penalty;
  });
  const winnerGains = allocateInteger(pool, capWeights(winnerCredits, MAX_PARTNER_RATIO));

  const loserBlames = losers.map((p) => {
    const expectedVsWinners = 1 / (1 + Math.pow(10, (ratingW - p.rating) / 400));
    return 1 - LOSS_UNDERDOG_BLEND + LOSS_UNDERDOG_BLEND * expectedVsWinners;
  });
  const loserLosses = allocateInteger(pool, capWeights(loserBlames, MAX_PARTNER_RATIO));

  return { winnerGains, loserLosses };
};

module.exports = async function(data) {
  const match = data.$trigger.payload || data.$trigger;

  const teamA = match.teamA || [];
  const teamB = match.teamB || [];
  const teamAScore = Number(match.teamAScore) || 0;
  const teamBScore = Number(match.teamBScore) || 0;

  // Determine winners and losers
  let winners, losers, scoreW, scoreL;
  if (teamAScore > teamBScore) {
    winners = teamA;
    losers = teamB;
    scoreW = teamAScore;
    scoreL = teamBScore;
  } else {
    winners = teamB;
    losers = teamA;
    scoreW = teamBScore;
    scoreL = teamAScore;
  }

  const { winnerGains, loserLosses } = calculateShift(
    winners,
    losers,
    scoreW,
    scoreL
  );

  const now = new Date().toISOString();

  const updatedWinners = winners
    .filter(p => p.userId)
    .map((player, i) => ({
      uuid: player.userId,
      rating: Math.max(RATING_FLOOR, (Number(player.rating) || 1450) + winnerGains[i]),
      rating_updated_at: now,
      matches_played: (Number(player.matchesPlayed) || 0) + 1,
      wins: (Number(player.wins) || 0) + 1
    }));

  const updatedLosers = losers
    .filter(p => p.userId)
    .map((player, i) => ({
      uuid: player.userId,
      rating: Math.max(RATING_FLOOR, (Number(player.rating) || 1450) - loserLosses[i]),
      rating_updated_at: now,
      matches_played: (Number(player.matchesPlayed) || 0) + 1,
      losses: (Number(player.losses) || 0) + 1
    }));

  const completedMatch = {
    match_key: `${match.completedAt}_${match.matchId}`,
    match_id: match.matchId,
    match_type: match.matchType,
    team_a: match.teamA,
    team_b: match.teamB,
    team_a_score: match.teamAScore,
    team_b_score: match.teamBScore,
    started_at: new Date(match.startedAt).toISOString(),
    completed_at: new Date(match.completedAt).toISOString(),
    players: [...teamA, ...teamB]
      .filter(p => p.userId)
      .map(p => ({ "directus_users_id": p.userId })),
    club: match.club,
    meta: match.meta || null
  };

  return {
    match,
    completedMatch,
    newPlayersRatings: [...updatedWinners, ...updatedLosers]
  };
};

